+/// Completed QUIC handshakes only need TLS exporter material. Packet traffic
+/// secrets and their key updates belong to the QUIC key schedule.
+pub(crate) struct QuicExporter {
+    ks: KeyScheduleSuite,
+    secret: OkmBlock,
+}
+
+impl QuicExporter {
+    pub(crate) fn export_keying_material(
+        &self,
+        out: &mut [u8],
+        label: &[u8],
+        context: Option<&[u8]>,
+    ) -> Result<(), Error> {
+        self.ks.export_keying_material(&self.secret, out, label, context)
+    }
+}
+
 impl KeyScheduleTraffic {
+    pub(crate) fn into_quic_exporter(self) -> QuicExporter {
+        QuicExporter {
+            ks: self.ks,
+            secret: self.current_exporter_secret,
+        }
+    }
